import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const lines = [];

  lines.push(invoice.number || 'DRAFT');
  lines.push(customerName);
  lines.push('');

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const unitPriceEuros = formatEuros(line.unitPrice);
    const lineTotalEuros = formatEuros(total);

    let lineText = `${String(line.qty).padStart(3)} ${line.name} ${unitPriceEuros} ${lineTotalEuros}`;
    if (discount > 0) {
      const discountEuros = formatEuros(discount);
      lineText += ` -${discountEuros}`;
    }
    lines.push(lineText);
  }

  lines.push('');

  const { subtotal, discount, total } = invoiceTotals(invoice);
  if (discount > 0) {
    const subtotalEuros = formatEuros(subtotal);
    const discountEuros = formatEuros(discount);
    lines.push(`Subtotal: ${subtotalEuros}`);
    lines.push(`Discount: -${discountEuros}`);
  }
  const totalEuros = formatEuros(total);
  lines.push(`Total: ${totalEuros}`);

  return lines.join('\n');
}

