    lines: [{ sku: 'DEV-HOUR', qty: 'five' }],
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'QTY_INVALID');
});

test('createInvoice fails with UNKNOWN_SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'UNKNOWN_SKU');
});

test('createInvoice fails with UNKNOWN_SKU on second line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'INVALID-SKU', qty: 1 },
    ],
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input lines array', () => {
  const inputLines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const originalLine = { ...inputLines[0] };

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: inputLines,
  });

  assert.deepStrictEqual(inputLines[0], originalLine);
});

test('createInvoice accepts valid dates', () => {
  const validDates = [
    '2026-01-01',
    '2026-12-31',
    '2025-02-28',
    '2024-02-29', // leap year
  ];

  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.strictEqual(result.ok, true, `Date ${date} should be valid`);
  }
});

test('createInvoice with products having different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines[0].vatRate, 21);
  assert.strictEqual(result.value.lines[1].vatRate, 9);
  assert.strictEqual(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
  };

  const total = lineTotal(line);
  assert.strictEqual(total, 47500);
});

test('lineTotal with qty 1', () => {
  const line = {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };

  const total = lineTotal(line);
  assert.strictEqual(total, 120000);
});

test('lineTotal with large qty', () => {
  const line = {
    sku: 'STICKER',
    name: 'Sticker sheet',
    qty: 1000,
    unitPrice: 50,
    vatRate: 21,
  };

  const total = lineTotal(line);
  assert.strictEqual(total, 50000);
});

test('lineTotal returns cents (integers only)', () => {
  const line = {
    sku: 'TEST',
    name: 'Test',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
  };

  const total = lineTotal(line);
  assert.strictEqual(Number.isInteger(total), true);
  assert.strictEqual(total, 28500);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 5,
        unitPrice: 9500,
        vatRate: 21,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 47500);
  assert.strictEqual(totals.total, 47500);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
      },
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 3,
        unitPrice: 8500,
        vatRate: 21,
      },
      {
        sku: 'LOGO-PACK',
        name: 'Logo package',
        qty: 1,
        unitPrice: 120000,
        vatRate: 21,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 95000 + 25500 + 120000);
  assert.strictEqual(totals.total, 240500);
});

test('invoiceTotals with empty lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 0);
  assert.strictEqual(totals.total, 0);
