test('invoiceTotals returns integer cents', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 7,
        unitPrice: 9500,
        vatRate: 21,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.strictEqual(Number.isInteger(totals.subtotal), true);
  assert.strictEqual(Number.isInteger(totals.total), true);
  assert.strictEqual(totals.subtotal, 66500);
  assert.strictEqual(totals.total, 66500);
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.strictEqual(result.ok, true);
  const totals = invoiceTotals(result.value);

  const expectedDev = 5 * 9500;
  const expectedDes = 2 * 8500;
  const subtotal = expectedDev + expectedDes;
  const discount = (subtotal * 5) / 100;
  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, discount);
  assert.strictEqual(totals.total, subtotal - discount);
});

test('addLine adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.strictEqual(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines.length, 2);
  assert.strictEqual(result.value.lines[1].sku, 'DES-HOUR');
  assert.strictEqual(result.value.lines[1].qty, 3);
  assert.strictEqual(result.value.lines[1].name, 'Design work (hour)');
  assert.strictEqual(result.value.lines[1].unitPrice, 8500);
