test('issueInvoice preserves all invoice data', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-05-20',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  assert.strictEqual(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, ['INV-2026-0001']);

  assert.strictEqual(result.ok, true);
  const issued = result.value;
  assert.strictEqual(issued.customerId, 'C-002');
  assert.strictEqual(issued.issueDate, '2026-05-20');
  assert.strictEqual(issued.lines.length, 2);
  assert.strictEqual(issued.lines[0].sku, 'DEV-HOUR');
  assert.strictEqual(issued.lines[0].qty, 10);
  assert.strictEqual(issued.lines[1].sku, 'DES-HOUR');
  assert.strictEqual(issued.lines[1].qty, 3);
  assert.strictEqual(issued.number, 'INV-2026-0002');
  assert.strictEqual(issued.status, 'issued');
});

