  const totalDiscount = devDiscount + desDiscount;
  const devVat = Math.round(((devTotal - devDiscount) * 21) / 100);
  const desVat = Math.round(((desTotal - desDiscount) * 21) / 100);
  const totalVat = devVat + desVat;

  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, totalDiscount);
  assert.strictEqual(totals.total, subtotal - totalDiscount + totalVat);
});

