});

test('lineVat with 9% VAT rate', () => {
  const line = {
    qty: 100,
    unitPrice: 37,
    vatRate: 9,
  };

  const vat = lineVat(line);
  const total = 100 * 37;
  const expectedVat = Math.round((total * 9) / 100);
  assert.strictEqual(vat, expectedVat);
});

test('invoiceTotals includes VAT in calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  const subtotal = 10 * 9500;
  const expectedVat = Math.round((subtotal * 21) / 100);

  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, 0);
  assert.strictEqual(totals.vat, expectedVat);
  assert.strictEqual(totals.total, subtotal + expectedVat);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  const devTotal = 10 * 9500;
  const printTotal = 100 * 37;
  const workshopTotal = 1 * 60000;
  const subtotal = devTotal + printTotal + workshopTotal;

  const devVat = Math.round((devTotal * 21) / 100);
  const printVat = Math.round((printTotal * 9) / 100);
  const workshopVat = 0;
  const expectedVat = devVat + printVat + workshopVat;

  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.vat, expectedVat);
  assert.strictEqual(totals.total, subtotal + expectedVat);
});

test('invoiceTotals with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  const subtotal = 10 * 9500;
  const discount = (subtotal * 5) / 100;
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round((amountAfterDiscount * 21) / 100);

  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, discount);
  assert.strictEqual(totals.vat, vat);
  assert.strictEqual(totals.total, subtotal - discount + vat);
});

test('invoiceTotals returns vat property', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  assert.strictEqual(typeof totals.vat, 'number');
  assert.strictEqual(totals.vat >= 0, true);
});

